from typing import List

def find_max_pyramid_size(A: List[int]) -> int:
    n = len(A)
    if n == 0:
        return 0

    b = [1] * n
    for i in range(1, n):
        if A[i] > b[i - 1]:
            b[i] = b[i - 1] + 1
        else:
            b[i] = A[i]

    c = [1] * n
    for i in range(n - 2, -1, -1):
        if A[i] > c[i + 1]:
            c[i] = c[i + 1] + 1
        else:
            c[i] = A[i]

    max_size = 0
    for i in range(n):
        peak = min(b[i], c[i])
        max_size = max(max_size, 2 * peak - 1)

    return max_size
